local function deathrattle(ctx,e)for _,k in ipairs(ctx:entity(e).keywords or{})do if k=="deathrattle"then return true end end return false end
local function upgrade(next_id)return{{event="card_played",timing="after",active_zones={"hand"},condition=function(ctx,self,event)return event.player==ctx:controller(self)and deathrattle(ctx,event.entity)end,effect=function(ctx,self)local n=ctx:get_data(self,"onyx_cards")+1;ctx:set_data(self,"onyx_cards",n);if n>=3 then cardlib.effects.transform(ctx, self,next_id)end end}}end
local function stone(id,name,text,count,next_id)local x={id=id,name=name,text=text,set="LOOTAPALOOZA",type="spell",class="rogue",collectible=false,spell_school="shadow",cost=5};if next_id then x.triggers=upgrade(next_id)end;x.on_play=function(ctx,self)ctx:set_data(self,"onyx_left",count);ctx:continue_with("onyx_choose")end;x.onyx_choose=function(ctx,self)local left=ctx:get_data(self,"onyx_left");local pool={};for _,e in ipairs(ctx:enemy_characters(self))do if ctx:entity(e).type=="minion"and ctx:get_data(self,"onyx_selected:"..e)==0 then pool[#pool+1]=e end end;if left>0 and #pool>0 then ctx:random_entity(pool,"onyx_select")else local targets={};for _,e in ipairs(ctx:minions())do if ctx:get_data(self,"onyx_selected:"..e)==1 then targets[#targets+1]=e end end;if #targets>0 then cardlib.effects.destroy_all(ctx, targets)end end end;x.onyx_select=function(ctx,self,e)ctx:set_data(self,"onyx_selected:"..e,1);local n=ctx:get_data(self,"onyx_left")-1;ctx:set_data(self,"onyx_left",n);ctx:continue_with("onyx_choose")end;return x end
local card=stone("LOOT_503","Lesser Onyx Spellstone","Destroy 1 random enemy minion.\n<i>(Play 3 <b>Deathrattle</b> cards to upgrade.)</i>",1,"LOOT_503t");card.api_version=1;card.collectible=true;card.rarity="rare";card.tokens={stone("LOOT_503t","Onyx Spellstone","Destroy up to 2 random enemy minions.",2,"LOOT_503t2"),stone("LOOT_503t2","Greater Onyx Spellstone","Destroy up to 3 random enemy minions.",3,nil)};return card
